import * as T from './vendor/three.module.js';
export const RELICS=[{name:'苔光生态瓶',icon:'🌿',note:'软木塞、苔藓小岛和发光种子',color:'#7dba85'},{name:'蜗牛邮差钟',icon:'🐌',note:'蜗壳钟盘、铜色触角和小信封',color:'#daa05e'},{name:'月航罗盘',icon:'🧭',note:'翡翠表壳、金色指针和月牙刻度',color:'#58aeb2'},{name:'蘑菇八音盒',icon:'🍄',note:'木质底座、红伞小屋和侧面发条',color:'#db7662'},{name:'星鲸许愿瓶',icon:'🐋',note:'蓝色小鲸、金色星环和星尘瓶盖',color:'#92a9ec'}];
export function createRelic(name){name=({四叶草:"苔光生态瓶",月亮罐:"月航罗盘",星光水晶:"蘑菇八音盒",发光石:"蘑菇八音盒",蘑菇标本:"蘑菇八音盒",时间沙漏:"星鲸许愿瓶"})[name]||name;const g=new T.Group();g.name=name;
 const mats=new Map();const material=(c,glass=false)=>{const k=c+glass;if(!mats.has(k))mats.set(k,new T.MeshStandardMaterial({color:c,roughness:glass?.15:.55,metalness:glass?.05:.12,transparent:glass,opacity:glass?.24:1,depthWrite:!glass}));return mats.get(k)};
 function part(geo,c,x=0,y=0,z=0,glass=false){const m=new T.Mesh(geo,material(c,glass));m.position.set(x,y,z);m.castShadow=!glass;m.receiveShadow=true;g.add(m);return m}
 const ball=(c,x,y,z,a,b=a,d=a)=>{const m=part(new T.SphereGeometry(1,20,12),c,x,y,z);m.scale.set(a,b,d);return m};
 const cyl=(c,x,y,z,r,h,r2=r)=>part(new T.CylinderGeometry(r,r2,h,24),c,x,y,z);
 const ring=(c,x,y,z,r,t=.018)=>part(new T.TorusGeometry(r,t,8,40),c,x,y,z);
 const box=(c,x,y,z,w,h,d)=>part(new T.BoxGeometry(w,h,d),c,x,y,z);
 function star(x,y,z,r=.05){const shape=new T.Shape();for(let i=0;i<10;i++){const a=Math.PI/2+i*Math.PI/5,rr=i%2?r*.45:r;const px=Math.cos(a)*rr,py=Math.sin(a)*rr;i?shape.lineTo(px,py):shape.moveTo(px,py)}shape.closePath();return part(new T.ExtrudeGeometry(shape,{depth:.015,bevelEnabled:false}),'#ffdc78',x,y,z)}
 const idx=RELICS.findIndex(r=>r.name===name);
 if(idx===0){cyl('#ae8150',0,.04,0,.19,.08);part(new T.CylinderGeometry(.19,.21,.36,28),'#b7ead2',0,.25,0,true);cyl('#8c6943',0,.46,0,.12,.10);ring('#d5b36b',0,.45,0,.13).rotation.x=Math.PI/2;ball('#577d44',0,.11,0,.17,.055,.16);for(let i=0;i<5;i++){const a=i*2.4;ball('#8fcf79',Math.cos(a)*.10,.16+i*.025,Math.sin(a)*.09,.055,.07,.035)}for(let i=0;i<3;i++)ball('#ffe4a1',Math.cos(i*2)*.10,.31+i*.03,.07,.025)}
 else if(idx===1){ball('#bbaa7c',0,.09,0,.29,.07,.14);ball('#d1a15d',-.035,.24,0,.19,.19,.10);const face=cyl('#fff1ce',-.035,.25,.115,.145,.02);face.rotation.x=Math.PI/2;ring('#ac7841',-.035,.25,.132,.155,.018);for(let i=0;i<12;i++){const a=i*Math.PI/6;ball('#7b654a',-.035+Math.sin(a)*.116,.25+Math.cos(a)*.116,.133,.009)}const h=box('#537d6e',-.035,.285,.15,.015,.085,.015);h.rotation.z=-.5;box('#537d6e',.005,.25,.15,.085,.013,.015);ball('#bbaa7c',.22,.14,0,.075,.11,.08);for(const z of [-.043,.043]){cyl('#ab9162',.235,.255,z,.012,.09);ball('#354f42',.235,.31,z,.019)}box('#f6e4b8',-.22,.16,.02,.095,.09,.07)}
 else if(idx===2){const base=cyl('#467f77',0,.13,0,.23,.12);base.rotation.x=Math.PI/2;const face=cyl('#f0dbad',0,.13,.075,.19,.018);face.rotation.x=Math.PI/2;ring('#d8b36a',0,.13,.10,.218,.019);const needle=part(new T.ConeGeometry(.035,.23,4),'#ce715e',0,.15,.12);needle.rotation.z=-.55;ball('#ddbc73',0,.13,.15,.029);for(let i=0;i<8;i++){const a=i*Math.PI/4;star(Math.sin(a)*.15,.13+Math.cos(a)*.15,.105,.019)}ring('#c6a460',0,.415,0,.052,.014);const lid=ring('#c6a460',0,.39,-.035,.20,.016);lid.rotation.x=-.3}
 else if(idx===3){cyl('#97704a',0,.04,0,.23,.08);cyl('#c09b68',0,.09,0,.21,.045);cyl('#efd5a2',0,.22,0,.11,.25);ball('#d96250',0,.37,0,.24,.12,.21);for(let i=0;i<6;i++){const a=i*1.05;ball('#fff0cf',Math.cos(a)*.14,.455,Math.sin(a)*.12,.033,.012,.03)}box('#6e8a63',0,.19,.108,.067,.11,.012);for(const x of [-.08,.08])ball('#ffce79',x,.26,.096,.019);const crank=cyl('#c6a055',.26,.12,0,.018,.10);crank.rotation.z=Math.PI/2;ball('#c6a055',.30,.17,0,.045,.02,.028)}
 else if(idx===4){part(new T.SphereGeometry(.245,28,20),'#b1cdf7',0,.27,0,true);cyl('#8e88b4',0,.055,0,.15,.07);cyl('#cca665',0,.50,0,.10,.075);star(0,.60,0,.06);ball('#719cbf',0,.26,0,.14,.075,.085);ball('#e7e5d4',.025,.227,.023,.10,.025,.06);for(const side of [-1,1])ball('#658aa9',-.13,.29,side*.045,.065,.027,.035);ball('#273f59',.10,.28,.067,.014);const orbit=ring('#dfbd75',0,.25,0,.29,.013);orbit.rotation.y=.7;orbit.rotation.x=.35;star(.20,.40,.09,.045);star(-.15,.16,.14,.035)}
 else{box('#c39a6f',0,.14,0,.32,.28,.28);box('#678659',0,.15,0,.05,.30,.30);box('#678659',0,.245,0,.34,.04,.30);ring('#ddc28e',0,.33,0,.055,.013)}
 g.userData.dispose=()=>{g.traverse(o=>o.geometry?.dispose());mats.forEach(m=>m.dispose())};return g;
}

